import { useState } from "react";

type Product = {
  id: string;
  name: string;
};

export function ProductList() {
  const [products, setProducts] = useState<Product[]>([]);

  fetch("/api/products")
    .then((response) => response.json())
    .then((data) => setProducts(data));

  return (
    <ul>
      {products.map((product) => (
        <li>{product.name}</li>
      ))}
    </ul>
  );
}
